// Track which videos we've already processed
const sd = $getWorkflowStaticData('global');
const lastCheck = sd.lastVideoCheckTime
  ? new Date(sd.lastVideoCheckTime)
  : new Date(Date.now() - 3 * 60 * 60 * 1000); // 3 hours ago on first run

const processedIds = new Set(sd.processedVideoIds || []);

const newVideos = [];

for (const item of $input.all()) {
  const mediaItems = item.json.mediaItems || [];
  const category = item.json._category;
  const contentType = item.json._content_type;
  const album = item.json._album;

  for (const video of mediaItems) {
    // Skip already-processed videos
    if (processedIds.has(video.id)) continue;

    const createdAt = new Date(video.mediaMetadata?.creationTime || 0);
    if (createdAt <= lastCheck) continue;

    newVideos.push({
      json: {
        googleId: video.id,
        filename: video.filename || 'untitled',
        title: (video.description || video.filename || 'New Video').replace(/\.[^/.]+$/, ''),
        description: video.description || '',
        category,
        content_type: contentType,
        album,
        photos_url: video.productUrl || '',
        created_at: createdAt.toISOString()
      }
    });
  }
}

// Returning empty array stops the workflow silently — no notification sent
return newVideos;

// Update state so we don't reprocess these videos
const sd = $getWorkflowStaticData('global');
sd.lastVideoCheckTime = new Date().toISOString();

// Track processed IDs (keep last 500)
const existing = sd.processedVideoIds || [];
const newIds = $input.all().map(item => item.json.googleId).filter(Boolean);
sd.processedVideoIds = [...new Set([...existing, ...newIds])].slice(-500);

// Build summary email
const count = $input.all().length;
const now = new Date().toLocaleString('en-US', {
  timeZone: 'America/Chicago',
  weekday: 'short', month: 'short', day: 'numeric',
  hour: 'numeric', minute: '2-digit'
});

let body = `Hi Kareesa,\n\n`;
body += `${count} new video${count !== 1 ? 's were' : ' was'} detected in Google Photos and sent to your Content Director.\n\n`;
body += `Caption drafts are ready for your review.\n\n`;
body += `VIDEOS PROCESSED\n----------------\n`;

for (const item of $input.all()) {
  const d = item.json;
  const label = d.category === 'gymnastics' ? 'GymnastDiva' : 'Real Estate';
  body += `  [${label}] ${d.title || d.filename || 'Untitled'}\n`;
}

body += `\nReview and approve captions at: http://localhost:5174 → GymnastDiva → Content Queue\n\n`;
body += `-- AICC Content Bot | ${now}`;

return [{ json: {
  subject: `${count} new video${count !== 1 ? 's' : ''} queued for review in AICC`,
  body
} }];
